// Facts, not prose. The agent that follows writes the digest; this node
// decides what it is allowed to write about.
//
// Everything below is computed from the API response. Nothing is invented
// here and nothing is asked of the model that it could get wrong: the counts,
// the names and the scores are all facts by the time the prompt is built, so
// the only thing the model contributes is the wording.

const run = $('Re-score the fleet').first().json;
const fleet = $('Fetch scored fleet').all().map((i) => i.json);

const inScope = fleet.filter((e) => e.in_model_scope);
const byLevel = { high: 0, medium: 0, low: 0 };
for (const e of inScope) byLevel[e.risk_level] = (byLevel[e.risk_level] || 0) + 1;

const top = [...inScope]
  .sort((a, b) => b.risk_score - a.risk_score)
  .slice(0, 5)
  .map((e) => ({
    id: e.id,
    building: e.building_name,
    zone: e.zone,
    score: Number(e.risk_score.toFixed(4)),
    level: e.risk_level,
    age_years: e.age_years,
    last_visit: e.last_visit_date
  }));

return [{
  json: {
    run: {
      scored: run.scored,
      skipped_no_telemetry: run.skipped_no_telemetry,
      out_of_scope: run.out_of_scope,
      readings_considered: run.readings_considered,
      window_hours: run.window_hours,
      model_version: run.model_version
    },
    fleet: { in_scope: inScope.length, total: fleet.length, by_level: byLevel },
    top_risks: top,
    generated_at: new Date().toISOString()
  }
}];
